local util = require 'XLua.util'
local CoWait = CS.Engine.Lib.CoWait
local KTool = CS.Engine.Lib.KTool

------------ import ------------
local UIModule = CS.Engine.UI.UIModule
------------ import ------------

------------ define ------------
local SellActionInputPath = 'Game.UI.Backpack.SellActionInput'
local StoreUtils = import('Game.UI.Store.StoreUtils')
local CommonUITitleNode = "Game.UI.Common.CommonUITitleNode"
------------ define ------------

local TYPE = {
    Use = 1,
    Sell = 2,
}

---@class SellActionDialog
---@field controller                    	Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field FontStyleButton1              	UnityEngine.RectTransform
---@field FontStyleButton2              	UnityEngine.RectTransform
---@field ImgIcon                       	UnityEngine.RectTransform
---@field TxtNumber                     	TMPro.TextMeshProUGUI
---@field TxtGetNumber                  	TMPro.TextMeshProUGUI
---@field TxtName                       	UnityEngine.RectTransform
---@field ImgGoodIcon                   	UnityEngine.RectTransform
---@field ImgBgRare                     	UnityEngine.RectTransform
---@field BtnClose                      	UnityEngine.RectTransform
---@field BuyNumGroup                      	UnityEngine.RectTransform @属入类型
---@field ImgLine                       	UnityEngine.RectTransform @线
---@field TxtObtain                     	UnityEngine.RectTransform @可获取显示
---@field ImgIcon                       	UnityEngine.RectTransform
---@field CommonUITitleNode2            	UnityEngine.RectTransform
local SellActionDialog = Class("SellActionDialog")

function SellActionDialog:__init()
    self.goodsVo = nil
    self.stackNum = nil
    self.type = TYPE.Sell
    self.equipId = nil
end

function SellActionDialog:__delete()
    self.goodsVo = nil
    self.stackNum = nil
    self.equipId = nil
    self.controller = nil
end

function SellActionDialog:RefreshTitle()
    local env = CfUtils.GetLuaScr(self.CommonUITitleNode2, CommonUITitleNode)
    if env then
        if self.type == TYPE.Use then
            env:Refresh(localize("使用道具"))
        else
            env:Refresh(localize("出售道具"))
        end
    end
end


function SellActionDialog:Awake()
    local  parameters = self.controller.Argument.parameters
    if parameters.goodsVo then
        self.goodsVo = parameters.goodsVo
        self.stackNum = parameters.stack
        self.type = checkNumber(parameters.type)
        self.equipId = parameters.equipId
    end
    if self.type == TYPE.Use then
        local txtTrans = self.TxtObtain.transform.parent:Find("TxtTitle")
        if not isNull(txtTrans) then
            CfUtils.FillText(txtTrans, localize("使用数量："))
        end
        KTool.SetActive(self.TxtNumber.gameObject, false)
        KTool.SetActive(self.TxtObtain.gameObject, false)
        KTool.SetActive(self.ImgLine.gameObject, false)
        KTool.SetActive(self.ImgIcon.gameObject, false)
    end
    ---@type SellActionInput
    local env = CfUtils.GetLuaScr(self.BuyNumGroup.gameObject, SellActionInputPath)
    env:FreshUI(checkNumber(self.stackNum))
    env:SetInputActionEvent(function(no)
        self:FreshGetGoodsInfo(no)
    end)
    SetButtonAction(self.BtnClose.gameObject, function()
        UIModule.BackDialog()
    end)
    SetButtonAction(self.FontStyleButton2, function()
        ---@type SellActionInput
        local env = CfUtils.GetLuaScr(self.BuyNumGroup.gameObject, SellActionInputPath)
        local num = env:GetInputNo()
        ----确认
        if self.type == TYPE.Sell then
            GameUtils.Request(Interfaces.BackpackSell, {
                consume = table.serialize({{goodsId = self.goodsVo.id, num = num, equipId = self.equipId}})
            }, function(request, response)
                if checkNumber(response.errCode)  == 0 then
                    ---成功了
                    local data = checkTable(response.data)
                    local rewards = checkTable(data.rewards)
                    local t = {}
                    table.insert(t, {goodsId = self.goodsVo.id, num = -num, playerItemId = self.equipId})
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(data.rewards)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards }
                                }
                        )
                    end
                    GoodsUtils.DrawRewards(t, true)

                    UIModule.CloseDialog(self.controller)
                end
            end)
        else
            GameUtils.Request(Interfaces.BackpackUse, {
                goodsId = self.goodsVo.id, num = num
            }, function(request, response)
                if checkNumber(response.errCode)  == 0 then
                    ---成功了
                    local data = checkTable(response.data)
                    local rewards = checkTable(data.rewards)
                    local t = {}
                    table.insert(t, {goodsId = self.goodsVo.id, num = -num, playerItemId = self.equipId})
                    GoodsUtils.DrawRewards(t, true)
                    if #rewards > 0 then
                        GoodsUtils.DrawRewards(rewards, true)
                        UIModule.OpenDialog(
                                {
                                    id = Constants.UITypeIds.UICommonRewardPop,
                                    parameters = { rewards = data.rewards }
                                }
                        )
                    end
                    UIModule.CloseDialog(self.controller)
                end
            end)
        end
    end)
    SetButtonAction(self.FontStyleButton1, function()
        ---取消
        UIModule.BackDialog()
    end)
end

function SellActionDialog:FreshUI()
    ---@type GoodsVo
    local goodsVo = self.goodsVo
    if goodsVo then
        CfUtils.FillImage(self.ImgBgRare, StoreUtils.GetGoodsBgByQuality(checkNumber(goodsVo.quality)))
        CfUtils.FillImage(self.ImgGoodIcon, goodsVo.photoPath)
        CfUtils.FillText(self.TxtName, goodsVo.name)
        CfUtils.FillText(self.TxtGetNumber, GoodsUtils.GetThingNo(goodsVo.id, self.equipId))
        self:FreshGetGoodsInfo(1)
        ---@type SellActionInput
        local env = CfUtils.GetLuaScr(self.BuyNumGroup.gameObject, SellActionInputPath)
        env:FreshUI(checkNumber(self.stackNum), 1)
    end
end

function SellActionDialog:FreshGetGoodsInfo(num)
    if self.type == TYPE.Sell then
        ---@type GoodsVo
        local goodsVo = self.goodsVo
        if goodsVo then
            print('--->>', goodsVo.sellitem, goodsVo.sellmoney)
            CfUtils.FillText(self.TxtNumber, tostring(checkNumber(goodsVo.sellmoney) * num))
            --CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(goodsVo.sellitem))
            CfUtils.FillImage(self.ImgIcon, GoodsConfMgr:GetInstance():GetPhotoPathById(Constants.Currency.GoldId))
        end
    end
end

function SellActionDialog:OnShow()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self:RefreshTitle()
    end))
    return coWait
end

function SellActionDialog:OnInitialize()
    ---@type Engine.Lib.CoWait
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
            self:FreshUI()
    end))
    return coWait
end

function SellActionDialog:OnFinalize()
    local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
        self = nil --lua层的gc需要
    end))
    return coWait
end

return SellActionDialog